import threading, time

class MonoId:
    def __init__(self, node_id: int, max_drift_ms: int = 500):
        self.node = node_id
        self.lock = threading.Lock()
        self.last_ms = -1
        self.seq = 0
        self.max_drift = max_drift_ms

    def _now_ms(self) -> int:
        return time.time_ns() // 1_000_000  # wall clock: comparable across hosts

    def next_id(self) -> int:
        with self.lock:
            now = self._now_ms()
            if now < self.last_ms:
                drift = self.last_ms - now
                # WHY stall-or-halt instead of clamp: clamping reuses
                # (timestamp, seq) pairs already emitted. Trade-off:
                # small drift costs latency, large drift costs availability.
                if drift > self.max_drift:
                    raise ClockWentBackwards(drift)
                while now < self.last_ms:
                    time.sleep(0.001)
                    now = self._now_ms()
            if now != self.last_ms:
                self.last_ms = now
                self.seq = 0
            else:
                self.seq += 1
                if self.seq > 4095:  # 12-bit sequence exhausted
                    # WHY spin to next ms: dropping or wrapping seq would
                    # duplicate. Trade-off: burst throughput capped at 4096/ms.
                    while now <= self.last_ms:
                        time.sleep(0.001)
                        now = self._now_ms()
                    self.last_ms = now
                    self.seq = 0
            return pack(self.last_ms, self.node, self.seq)

class ClockWentBackwards(Exception):
    pass
